        ConfidentBoulwareAgent,
        ConfidentRouterAgent,
        EvidenceAgent,
        ExplorerAgent,
        GuardedAgent,
        LLMAgent,
        NaiveAgent,
        RationalAgent,
        ReciprocalAgent,
        RouterAgent,
        SmartAgent,
        SwitcherAgent,
        llm_from_env,
    )

    if name == "naive":
        return NaiveAgent
    if name == "rational":
        return RationalAgent
    if name == "explorer":
        return ExplorerAgent
    if name == "anchor":
        return AnchorAgent
    if name == "switcher":
        return SwitcherAgent
    if name == "boulware":
        return BoulwareAgent
    if name == "router":
        return RouterAgent
    if name == "smart":
        return SmartAgent
    if name == "confident":
        return ConfidentAgent
    if name == "confident_boulware":
        return ConfidentBoulwareAgent
    if name == "confident_router":
        return ConfidentRouterAgent
